/** An authored explanation linked to exact native symbols and a conceptual illustration. */
export type Algorithm = { id: string; title: string; category: string; apis: string[]; summary: string; use: string; steps: [string, string, string]; caveat: string; knobs: string; diagram: string; formula: string }
const entry = (id: string, title: string, category: string, apis: string[], summary: string, use: string, steps: Algorithm['steps'], caveat: string, knobs: string, diagram: string, formula = ''): Algorithm => ({ id, title, category, apis, summary, use, steps, caveat, knobs, diagram, formula })

/** The visual atlas. Each record explains a distinct method, with limits and tuning guidance. */
export const algorithms: Algorithm[] = [
  entry('gaussian-blur', 'Gaussian blur', 'Filtering', ['GaussianBlur', 'getGaussianKernel'], 'Replace each pixel with a weighted average that gives nearby pixels more influence.', 'Reduce sensor noise before finding edges, build image pyramids, or soften detail at a controlled scale.', ['Place a bell-shaped kernel around the current pixel.', 'Multiply neighbours by their distance-dependent weights.', 'Sum the weighted values, then move the kernel to the next pixel.'], 'Strong smoothing removes small features and blends across object boundaries. Border modes change the values near the image edge.', 'sigmaX controls the spatial scale; ksize limits the support. Use an odd kernel size, or let supported zero dimensions derive it from sigma.', 'convolution', 'G(x,y) ∝ exp(−(x²+y²) / (2σ²))'),
  entry('box-filter', 'Box filtering', 'Filtering', ['blur', 'boxFilter', 'sqrBoxFilter'], 'Average a rectangular neighbourhood with equal weight at every position.', 'Compute local means, local variance, and inexpensive smoothing over large windows.', ['Select a rectangular window.', 'Sum its samples with equal weights.', 'Divide by the area when normalization is enabled.'], 'Equal weights can leave block-shaped blur and suppress edges. sqrBoxFilter averages squared values, useful with a local mean for variance.', 'ksize chooses the neighbourhood; normalize selects an average or a sum; ddepth controls overflow and precision.', 'convolution', 'mean = Σ window / number of samples'),
  entry('median-filter', 'Median filtering', 'Filtering', ['medianBlur'], 'Choose the middle value of a pixel neighbourhood instead of averaging its intensities.', 'Remove isolated bright or dark specks while keeping many sharp boundaries.', ['Gather the neighbourhood values for one channel.', 'Order the values from dark to light.', 'Write the middle value at the centre.'], 'The method removes thin lines along with noise when they occupy less than half the window. Supported depths depend on kernel size.', 'ksize must be odd and greater than one. Increase it only when the unwanted specks are larger.', 'convolution', 'output(x,y) = median(neighbourhood(x,y))'),
  entry('bilateral-filter', 'Bilateral filtering', 'Filtering', ['bilateralFilter'], 'Smooth nearby pixels only when their colours are also similar.', 'Reduce noise while retaining strong object boundaries, often before stylization or segmentation.', ['Measure each neighbour’s spatial distance.', 'Measure its colour distance from the centre.', 'Combine both weights and normalize their weighted sum.'], 'Large windows are expensive. Strong texture may be flattened, and weak edges can still blur.', 'sigmaSpace sets the spatial reach; sigmaColor sets how different colours may mix; d sets the diameter.', 'convolution', 'weight = spatial Gaussian × colour Gaussian'),
  entry('filter2d', 'Custom correlation kernels', 'Filtering', ['filter2D', 'sepFilter2D', 'filter2Dp'], 'Apply your own linear filter to every pixel neighbourhood.', 'Build sharpening, derivative, embossing, or application-specific linear filters.', ['Align the kernel anchor with the output pixel.', 'Multiply kernel coefficients and matching input samples.', 'Add the products and delta, then convert to the output depth.'], 'filter2D computes correlation: it does not flip the kernel. Flip the kernel and adjust the anchor when true convolution is required.', 'Use float or signed output for negative responses. A separable kernel can run as a horizontal pass followed by a vertical pass.', 'convolution', 'dst(x,y) = Σ kernel(i,j) · src(x+i−ax,y+j−ay) + delta'),
  entry('sobel', 'Sobel derivatives', 'Edges', ['Sobel', 'getDerivKernels'], 'Measure image change along x or y while smoothing in the perpendicular direction.', 'Estimate edge strength and orientation, normals, or inputs to gradient-based feature methods.', ['Smooth across the direction perpendicular to the derivative.', 'Subtract weighted samples on opposite sides.', 'Keep the signed response or combine x and y magnitudes.'], 'An unsigned output clips negative derivatives. Convert to a signed or floating matrix before interpreting direction.', 'dx and dy choose derivative orders; ksize changes support; scale keeps magnitudes comparable across kernels.', 'gradient', '|∇I| = √(Ix² + Iy²)'),
  entry('scharr', 'Scharr derivatives', 'Edges', ['Scharr'], 'Use a specialized 3×3 derivative kernel with improved rotational symmetry.', 'Get small-kernel image gradients when orientation accuracy matters.', ['Weight the centre row or column more strongly.', 'Subtract the opposite side to estimate a derivative.', 'Combine horizontal and vertical responses for edge orientation.'], 'It is still a local derivative and responds to noise. Blur first when the image is noisy.', 'Choose dx=1, dy=0 or dx=0, dy=1 and use signed output. Scale differs from a 3×3 Sobel response.', 'gradient', 'x kernel = [−3,0,3; −10,0,10; −3,0,3]'),
  entry('laplacian', 'Laplacian', 'Edges', ['Laplacian'], 'Measure the second spatial derivative, highlighting rapid changes in image intensity.', 'Find fine detail, build sharpening filters, or estimate focus from high-frequency content.', ['Estimate the second derivative along x.', 'Estimate the second derivative along y.', 'Add the responses at each pixel.'], 'Noise creates a strong response too. Variance of the Laplacian depends on exposure, texture, scale and noise, not just focus.', 'ksize sets derivative support; use a signed output and control smoothing before comparing images.', 'gradient', '∇²I = Ixx + Iyy'),
  entry('canny', 'Canny edges', 'Edges', ['Canny'], 'Turn image gradients into thin, connected edge chains using two thresholds.', 'Trace object boundaries for geometry, contour extraction, or line detection.', ['Measure gradient magnitude and direction.', 'Suppress responses that are not local maxima across the edge.', 'Keep strong edges and weak edges connected to them.'], 'Canny does not itself identify objects. Noise, texture and illumination can produce extra boundaries. Apply suitable smoothing before the call.', 'threshold1 and threshold2 govern hysteresis. apertureSize controls the derivative kernel; L2gradient selects Euclidean magnitude.', 'edges', 'strong ≥ high; weak ≥ low survives only if connected'),
  entry('threshold', 'Global thresholding', 'Segmentation', ['threshold'], 'Divide pixels using one intensity threshold, or choose it automatically with Otsu or the triangle method.', 'Separate a well-lit foreground from a background with a different intensity distribution.', ['Read the intensity at a pixel.', 'Compare it with a global threshold.', 'Write the selected binary, truncated, or retained value.'], 'One threshold struggles with shadows and uneven illumination. Otsu is most useful when a histogram separates into distinct populations.', 'type controls the rule; maxval sets the foreground value. The returned scalar is the threshold that was used.', 'threshold', 'binary(x,y) = I(x,y) > T ? maxval : 0'),
  entry('adaptive-threshold', 'Adaptive thresholding', 'Segmentation', ['adaptiveThreshold'], 'Compute a different intensity threshold for each local neighbourhood.', 'Read documents or segment surfaces under slowly varying illumination.', ['Estimate a local mean or Gaussian-weighted mean.', 'Subtract the offset C.', 'Threshold the centre pixel against its local estimate.'], 'Small windows follow texture and noise. Large windows stop adapting to illumination changes. The input is an 8-bit single-channel image.', 'blockSize must be odd and greater than one; C shifts the threshold; choose mean or Gaussian weighting.', 'threshold', 'T(x,y) = local statistic(x,y) − C'),
  entry('erosion', 'Erosion', 'Morphology', ['erode'], 'Shrink a bright mask by taking the minimum under a structuring element.', 'Remove small bright specks, break thin bridges, or require an entire neighbourhood to be foreground.', ['Move a structuring element over the mask.', 'Inspect all covered pixel values.', 'Write the minimum; binary foreground survives only when all covered pixels are foreground.'], 'Thin valid structures disappear. Grayscale erosion is a minimum filter, not merely a binary shape operation.', 'Kernel shape encodes which neighbours matter; iterations repeat the operation and increase the shrinkage.', 'morphology', 'erosion(A,B)(x) = min over b∈B of A(x+b)'),
  entry('dilation', 'Dilation', 'Morphology', ['dilate'], 'Expand a bright mask by taking the maximum under a structuring element.', 'Connect nearby foreground regions, thicken lines, or expand a region of interest.', ['Place the kernel at one output position.', 'Look for any foreground within its footprint.', 'Write the maximum and advance to the next position.'], 'Separate objects may merge. A large kernel can close a gap that carries important structure.', 'Choose the structuring-element shape, anchor and number of iterations to match the scale of the gap.', 'morphology', 'dilation(A,B)(x) = max over b∈B of A(x+b)'),
  entry('morphology', 'Opening, closing and morphology', 'Morphology', ['morphologyEx', 'getStructuringElement'], 'Compose erosions and dilations to remove small structures or measure their boundaries.', 'Clean segmentation masks, fill small holes, or isolate bright and dark details at a selected scale.', ['Choose a structuring element that represents the feature scale.', 'Opening erodes then dilates; closing dilates then erodes.', 'Gradient, top-hat and black-hat subtract the appropriate filtered images.'], 'Opening removes protrusions; closing fills gaps. Neither operation reconstructs the true hidden boundary.', 'op selects opening, closing, gradient, top-hat or black-hat. Kernel shape matters as much as its size.', 'morphology', 'open = dilate(erode(A)); close = erode(dilate(A))'),
  entry('distance-transform', 'Distance transforms', 'Morphology', ['distanceTransform', 'distanceTransformWithLabels'], 'For every nonzero pixel, measure the distance to the nearest zero pixel.', 'Estimate object thickness, find interior centres, create feathered masks, or assign pixels to nearby boundaries.', ['Treat zero pixels as distance sources.', 'Propagate distance through the chosen metric.', 'Optionally attach the identity of the nearest zero component or pixel.'], 'Approximate masks and precise Euclidean distance have different error bounds. The labelled variant has its own supported settings.', 'distanceType selects L1, L2 or chessboard distance; maskSize controls approximation; labelType controls label identity.', 'distance', 'D(p) = min over q with mask(q)=0 of distance(p,q)'),
  entry('connected-components', 'Connected components', 'Segmentation', ['connectedComponents', 'connectedComponentsWithStats'], 'Give every connected foreground region a distinct integer label.', 'Count objects, filter tiny regions, or measure areas, bounding boxes and centroids.', ['Visit each foreground pixel and its selected neighbours.', 'Merge labels that refer to the same connected region.', 'Accumulate per-label statistics and centroids.'], 'Touching objects become one component. Label numbers are identifiers; they do not necessarily follow size or position.', 'Connectivity 4 uses shared edges; 8 also joins diagonals. Label zero is the background.', 'components', 'component = maximal connected set of nonzero pixels'),
  entry('contours', 'Contour tracing', 'Segmentation', ['findContours', 'drawContours'], 'Trace the boundary of each binary region as an ordered sequence of points.', 'Measure outlines, distinguish holes, simplify shapes or draw boundaries.', ['Locate an unvisited boundary pixel.', 'Follow the region boundary in order.', 'Record points and, when requested, parent-child contour relationships.'], 'Contour area and foreground pixel count are different measurements. Retrieval and approximation choices change the output topology and point count.', 'RETR_EXTERNAL keeps outer boundaries; RETR_TREE retains nesting. CHAIN_APPROX_SIMPLE removes redundant points on straight runs.', 'contour', 'binary mask → ordered boundaries + hierarchy'),
  entry('polygon-approximation', 'Polygon approximation', 'Shape', ['approxPolyDP'], 'Replace a dense curve with fewer vertices while limiting geometric deviation.', 'Simplify contours, identify approximate quadrilaterals, or reduce geometry for rendering.', ['Connect the end points of a curve segment.', 'Find the point farthest from that segment.', 'Split if its deviation exceeds epsilon, then repeat.'], 'A high epsilon erases real corners. It is a geometric tolerance, not a guarantee of the intended semantic shape.', 'epsilon uses the same coordinate units as the contour; closed specifies whether the curve is a loop.', 'contour', 'maximum retained deviation controlled by ε'),
  entry('convex-hull', 'Convex hulls and defects', 'Shape', ['convexHull', 'convexityDefects', 'isContourConvex'], 'Wrap a point set in its smallest convex boundary and measure inward deviations.', 'Estimate envelopes, detect concavities, or build coarse collision shapes.', ['Order the points along the outside of the set.', 'Discard turns that bend inward.', 'For convexity defects, compare the original contour with hull edges.'], 'The hull intentionally discards concave detail. Defect depth uses the native fixed-point representation described in the API.', 'returnPoints chooses coordinates or contour indices. convexityDefects needs hull indices.', 'contour', 'hull = smallest convex set containing all points'),
  entry('moments', 'Image and contour moments', 'Shape', ['moments', 'HuMoments', 'matchShapes'], 'Summarize how a region’s mass is distributed over its coordinates.', 'Compute centroids and orientation, or compare shape descriptors under translation, scale and rotation.', ['Accumulate powers of x and y weighted by pixel mass.', 'Shift to the centroid and normalize scale.', 'Combine normalized moments into descriptors such as Hu invariants.'], 'Small contour changes and numerical range affect high-order moments. A zero-area region has no defined centroid.', 'binaryImage treats nonzero pixels as equal mass; matchShapes chooses a distance between Hu-based descriptors.', 'shape', 'centroid = (m10 / m00, m01 / m00)'),
  entry('watershed', 'Marker-based watershed', 'Segmentation', ['watershed'], 'Grow labelled regions across an image until competing regions meet at boundaries.', 'Separate touching objects when you can provide reliable foreground and background seeds.', ['Create distinct positive marker labels and leave unknown pixels at zero.', 'Expand markers through the image’s local contrast structure.', 'Mark meeting boundaries with −1 in the output marker matrix.'], 'Poor markers produce poor segments. Watershed boundaries alone do not solve object recognition.', 'Use a 3-channel 8-bit image and a signed 32-bit marker matrix. The markers are modified in place.', 'segmentation', 'known seeds → competing region growth → boundaries'),
  entry('grabcut', 'GrabCut', 'Segmentation', ['grabCut'], 'Alternate colour-model estimation and graph cuts to separate foreground from background.', 'Extract an object from a loose rectangle or a few foreground/background hints.', ['Initialize definite and probable foreground/background labels.', 'Fit colour mixtures to the current foreground and background.', 'Optimize the cut using colour likelihoods and neighbourhood smoothness, then refine.'], 'Similar foreground/background colours and fine translucent structures are difficult. Preserve the model matrices when continuing an existing solve.', 'mode chooses rectangle or mask initialization; iterCount controls refinement; mask labels are categories, not alpha values.', 'segmentation', 'energy = colour fit + boundary smoothness'),
  entry('resize', 'Image resizing', 'Geometry', ['resize'], 'Sample the source on a new pixel grid at a different resolution.', 'Create thumbnails, image pyramids or model inputs.', ['Map each destination pixel back to a source location.', 'Choose neighbouring source samples using the interpolation rule.', 'Combine the samples into one output pixel.'], 'Downsampling can alias high-frequency texture. Premultiply RGB before resizing transparent images to avoid coloured fringes.', 'INTER_AREA is useful for shrinking; nearest preserves discrete labels; linear and cubic trade sharpness against cost.', 'resampling', 'destination grid → source coordinates → interpolation'),
  entry('remap', 'Arbitrary remapping', 'Geometry', ['remap', 'convertMaps'], 'Provide a source coordinate for every destination pixel.', 'Undistort lenses, apply displacement fields, align plates or implement custom image warps.', ['Build x and y maps in destination coordinates.', 'Look up each requested source location.', 'Interpolate neighbours and apply the border rule when sampling outside the image.'], 'These are inverse sampling maps. A forward motion field cannot be passed directly without the appropriate inversion. Alpha and colour should share the same maps.', 'map1/map2 encode coordinates; interpolation controls sampling; borderMode governs unavailable pixels.', 'resampling', 'dst(x,y) = src(mapX(x,y), mapY(x,y))'),
  entry('affine-warp', 'Affine transformations', 'Geometry', ['warpAffine', 'getAffineTransform', 'getRotationMatrix2D', 'estimateAffine2D', 'estimateAffinePartial2D'], 'Map points with a linear transform plus translation, preserving straight lines and parallelism.', 'Align images under rotation, scale, shear and translation, or rotate around a chosen centre.', ['Estimate or construct a 2×3 transformation matrix.', 'Map the output grid back to the input grid.', 'Resample the source and fill uncovered borders.'], 'Affine models cannot describe general perspective distortion. Robust estimation needs enough well-distributed correspondences.', 'WARP_INVERSE_MAP declares the direction of a supplied warp; dsize chooses the output canvas.', 'warp', '[x′,y′]ᵀ = A[x,y]ᵀ + t'),
  entry('homography', 'Homography and RANSAC', 'Geometry', ['findHomography', 'findHomography1', 'getPerspectiveTransform', 'warpPerspective', 'perspectiveTransform'], 'Estimate a projective mapping between two views of a plane, rejecting inconsistent point matches.', 'Locate a poster, rectify a document, or align a planar surface seen from a new viewpoint.', ['Propose a homography from a small sample of correspondences.', 'Measure reprojection errors and mark the agreeing matches as inliers.', 'Refine the mapping using the accepted correspondences.'], 'Parallax from a 3D scene cannot generally be explained by one homography. Collinear points and repeated texture make estimation unstable.', 'Choose a robust estimation method and reprojection threshold in pixel units. Inspect the inlier mask, spatial coverage and reprojection error.', 'matching', 's[x′,y′,1]ᵀ = H[x,y,1]ᵀ'),
  entry('polar-warp', 'Polar and log-polar warps', 'Geometry', ['warpPolar'], 'Re-express an image using angle and radius around a chosen centre.', 'Turn rotation into a shift and, with logarithmic radius, scale change into another shift.', ['Choose the common centre of the transformation.', 'Map each output row to an angle and each column to a radius.', 'Sample the corresponding Cartesian coordinate in the source.'], 'The centre must be meaningful and stable. Sampling near the centre and the angular seam can distort detail.', 'WARP_POLAR_LOG uses log radius; maxRadius and dsize set the covered region and sampling density.', 'polar', 'x = cx + r cos θ; y = cy + r sin θ'),
  entry('image-pyramids', 'Gaussian and Laplacian pyramids', 'Filtering', ['pyrDown', 'pyrUp'], 'Represent the same image at a sequence of progressively coarser scales.', 'Find large motion cheaply, blend images at multiple scales, or detect features across scale.', ['Smooth the image to reduce aliasing.', 'Downsample to create the next smaller level.', 'For a Laplacian pyramid, subtract an expanded coarse level from the fine level.'], 'pyrUp interpolates an image; it does not recover details lost by pyrDown. Odd dimensions require attention to output size.', 'Choose enough levels to make the largest expected displacement small at the coarsest scale.', 'pyramid', 'Lk = Gk − expand(Gk+1)'),
  entry('template-matching', 'Template matching', 'Matching', ['matchTemplate'], 'Slide a patch across an image and score how well it agrees at each location.', 'Find a known drawing, UI element or local translation when scale and orientation are stable.', ['Place the template at each valid image position.', 'Compute squared difference, correlation, or normalized correlation.', 'Find the best response and optionally refine the peak.'], 'The template is not automatically rotation or scale invariant. Flat templates, repeated texture and partial occlusion can make the peak ambiguous.', 'TM_SQDIFF methods prefer minima; correlation methods prefer maxima. Mask support and normalization depend on the chosen method.', 'template', 'SQDIFF(x,y) = Σ (image patch − template)²'),
  entry('phase-correlation', 'Phase correlation', 'Matching', ['phaseCorrelate', 'createHanningWindow'], 'Estimate translation from the phase relationship between two images in the frequency domain.', 'Measure global image shifts, stabilize a translating scene, or compare log-polar representations.', ['Transform both images into the frequency domain.', 'Normalize their cross-power spectrum.', 'Transform back and locate the correlation peak.'], 'Changing content, occlusion and periodic texture weaken the estimate. Windowing helps reduce discontinuities at the image boundary.', 'Use matching single-channel float images. The response score measures peak concentration and should be checked alongside the shift.', 'frequency', 'R = (F1 · conjugate(F2)) / |F1 · conjugate(F2)|'),
  entry('ecc-alignment', 'ECC alignment', 'Matching', ['findTransformECC', 'computeECC'], 'Refine a warp by maximizing enhanced correlation between an image and a template.', 'Track a roughly aligned patch or improve an initial translation, affine transform or homography.', ['Warp the current image using an initial transform.', 'Measure normalized photometric agreement and its local gradient.', 'Update the warp parameters until the stopping criterion is met.'], 'This is a local optimizer. Large displacements, occlusion or a poor initial warp can cause failure to converge.', 'motionType controls the model; criteria sets iteration and accuracy limits; a mask excludes unsuitable template pixels.', 'ecc', 'iterate warp parameters to increase normalized correlation'),
  entry('orb', 'ORB features', 'Features', ['ORB', 'ORB_create'], 'Detect oriented corners across an image pyramid and describe them with compact binary tests.', 'Match textured objects quickly on CPU, track scenes, or build lightweight recognition pipelines.', ['Find FAST corners at several pyramid levels.', 'Estimate a dominant orientation for each retained patch.', 'Rotate binary intensity comparisons to build a descriptor.'], 'Large viewpoint changes and repeated or textureless surfaces remain difficult. Binary descriptors require a suitable Hamming distance.', 'nfeatures limits retained points; scaleFactor and nlevels cover scale; WTA_K affects the correct Hamming norm.', 'features', 'keypoint → oriented patch → binary descriptor'),
  entry('sift', 'SIFT features', 'Features', ['SIFT', 'SIFT_create'], 'Detect scale-space extrema and describe local gradient distributions around them.', 'Match textured scenes with substantial changes in scale or orientation.', ['Find extrema across differences of Gaussian images.', 'Reject unstable points and estimate scale and orientation.', 'Accumulate local gradient histograms into a descriptor.'], 'Descriptors are larger and slower than compact binary features. Low texture, motion blur and repeated patterns reduce reliable matches.', 'contrastThreshold rejects weak extrema; edgeThreshold rejects edge-like points; nfeatures caps output. Match floating descriptors with L2.', 'features', 'scale-space extrema → orientation → gradient histogram'),
  entry('akaze', 'AKAZE features', 'Features', ['xfeatures2d_AKAZE'], 'Find and describe features in a nonlinear scale space that preserves important boundaries.', 'Match objects when an edge-preserving scale representation and compact descriptors are useful.', ['Build nonlinear diffusion levels.', 'Detect stable responses across those levels.', 'Describe oriented patches using the selected descriptor mode.'], 'Descriptor modes have different output formats and distance metrics. Do not assume every AKAZE configuration produces the same binary descriptor.', 'threshold affects detector sensitivity; octave settings control scale; descriptor_type selects the representation.', 'features', 'nonlinear scale space → keypoints → descriptor'),
  entry('brisk', 'BRISK features', 'Features', ['xfeatures2d_BRISK'], 'Describe scale-space keypoints using intensity comparisons on concentric sampling rings.', 'Obtain scale- and rotation-aware binary features for fast matching.', ['Detect candidate keypoints across scales.', 'Use long-distance sample pairs to estimate orientation.', 'Compare short-distance pairs to construct descriptor bits.'], 'Small blurred patches and repeated textures can make binary comparisons unreliable.', 'thresh controls detection; octaves control scale coverage; patternScale changes descriptor sampling support.', 'features', 'ring samples → orientation → binary comparisons'),
  entry('fast', 'FAST corners', 'Features', ['FastFeatureDetector'], 'Look for a contiguous arc of brighter or darker pixels around a candidate centre.', 'Detect many corners quickly before tracking or descriptor computation.', ['Sample a small circle around each pixel.', 'Test whether a long contiguous arc differs enough from the centre.', 'Optionally keep only local maxima of the corner response.'], 'FAST alone supplies no descriptor and no scale normalization. Noise affects the intensity test.', 'threshold controls required contrast; nonmaxSuppression reduces clusters of adjacent detections.', 'features', 'corner: contiguous ring arc differs from centre by more than T'),
  entry('good-features', 'Shi-Tomasi and Harris corners', 'Features', ['goodFeaturesToTrack', 'cornerHarris', 'cornerMinEigenVal', 'cornerSubPix', 'GFTTDetector'], 'Find locations whose local gradients constrain motion in both image directions.', 'Choose stable points for sparse optical flow or refine calibration corners.', ['Accumulate local gradient products into a 2×2 matrix.', 'Score both-direction intensity change using eigenvalues or a Harris response.', 'Keep strong separated peaks; optionally refine them to subpixel positions.'], 'A straight edge constrains movement across itself but poorly along itself. Corners can still disappear under occlusion or lighting changes.', 'qualityLevel filters relative strength; minDistance spreads points; blockSize controls the neighbourhood.', 'features', 'Shi-Tomasi score = min(λ1, λ2)'),
  entry('mser', 'Maximally stable extremal regions', 'Features', ['MSER'], 'Find connected regions that change little over a range of intensity thresholds.', 'Detect text-like regions, blobs or stable region features under contrast changes.', ['Sweep intensity thresholds through the image.', 'Track how connected regions grow and merge.', 'Keep regions whose area changes slowly across neighbouring thresholds.'], 'Stable intensity regions are candidate structures, not recognized characters or objects.', 'delta controls the threshold comparison interval; area and variation settings control retained regions.', 'segmentation', 'stability measures relative area change across thresholds'),
  entry('brute-force-matching', 'Brute-force descriptor matching', 'Matching', ['BFMatcher', 'BFMatcher_create', 'DescriptorMatcher'], 'Compare each query descriptor with every training descriptor using a chosen distance.', 'Establish candidate correspondences before estimating a geometric transformation.', ['Compute descriptor distances.', 'Select the nearest match or nearest k neighbours.', 'Filter ambiguous candidates and validate them with image geometry.'], 'A nearest descriptor is not automatically the same physical point. Use cross-checking, ratio tests where appropriate, and robust geometric verification.', 'Use L2 for floating descriptors, Hamming for ordinary binary descriptors, and Hamming2 for ORB configurations that require it.', 'matching', 'best match = argmin descriptor distance'),
  entry('flann', 'FLANN nearest neighbours', 'Matching', ['FlannBasedMatcher', 'flann_Index', 'ANNIndex'], 'Organize descriptors so nearest-neighbour queries can avoid an exhaustive scan.', 'Search larger descriptor collections where approximate neighbours are an acceptable speed tradeoff.', ['Build an index suited to the descriptor representation.', 'Visit promising parts of the index for each query.', 'Return nearest candidates and their distances.'], 'Index type, distance and descriptor dtype must agree. Approximation can miss the exact nearest neighbour.', 'Tree or hash settings govern indexing; search checks trade query cost against recall. Keep the training data valid as required by the index API.', 'matching', 'index build cost + reduced work per query'),
  entry('hough-lines', 'Hough line detection', 'Geometry', ['HoughLines', 'HoughLinesP'], 'Let edge pixels vote for lines in a parameter space.', 'Detect document borders, lane-like structures or long straight edges.', ['Represent a line by its normal angle and distance from the origin.', 'Accumulate votes from compatible edge pixels.', 'Find strong peaks or supported line segments.'], 'Texture creates extra votes. The probabilistic variant reports finite segments and depends on gap and length settings.', 'rho and theta set accumulator resolution; threshold sets vote support; HoughLinesP adds minLineLength and maxLineGap.', 'hough', 'ρ = x cos θ + y sin θ'),
  entry('hough-circles', 'Hough circle detection', 'Geometry', ['HoughCircles'], 'Use edge and gradient evidence to find circular structures.', 'Locate approximately circular markers, cells or manufactured parts.', ['Measure edges and their gradient directions.', 'Accumulate candidate centre evidence.', 'Estimate radii and retain sufficiently supported circles.'], 'The supported methods use different scoring rules. Reflections, overlapping circles and perspective ellipses can confuse circular detection.', 'minDist separates centres; minRadius/maxRadius narrow the search; tune the thresholds for the selected method.', 'hough', '(x−cx)² + (y−cy)² = r²'),
  entry('optical-flow-lk', 'Lucas-Kanade optical flow', 'Motion', ['calcOpticalFlowPyrLK', 'SparsePyrLKOpticalFlow'], 'Follow selected points by finding the small displacement that best aligns each local patch.', 'Track feature points between nearby frames, estimate motion, or maintain an object pose after detection.', ['Build a coarse-to-fine image pyramid.', 'Solve local brightness-constancy equations for each patch.', 'Refine at finer levels and return status/error for each point.'], 'Points on flat regions or edges may be underconstrained. Occluded or failed points must be rejected using status and further consistency checks.', 'winSize controls patch support; maxLevel handles larger motion; criteria controls refinement. Forward-backward checking can reveal inconsistent tracks.', 'flow', 'Ix·u + Iy·v + It ≈ 0'),
  entry('optical-flow-farneback', 'Farneback dense optical flow', 'Motion', ['calcOpticalFlowFarneback', 'FarnebackOpticalFlow'], 'Estimate a displacement vector at every pixel using local polynomial approximations.', 'Visualize dense motion, align neighbouring frames, or initialize motion-aware processing.', ['Approximate each local neighbourhood with a quadratic polynomial.', 'Infer displacement from how polynomial coefficients change.', 'Average and refine the field across pyramid levels.'], 'A dense field includes uncertain pixels too. Occlusion, uniform areas and illumination changes need separate confidence handling.', 'pyr_scale and levels set motion range; winsize sets support; poly_n/poly_sigma tune the local polynomial approximation.', 'flow', 'dense output: (horizontal displacement, vertical displacement) per pixel'),
  entry('optical-flow-dis', 'DIS dense optical flow', 'Motion', ['DISOpticalFlow'], 'Combine fast patch alignment with spatial propagation and dense refinement.', 'Estimate dense motion on CPU when latency matters.', ['Estimate patch displacement with inverse search.', 'Propagate useful proposals to neighbouring patches.', 'Densify and optionally refine the resulting flow.'], 'Presets trade speed against detail and robustness. Small structures and occlusion boundaries can be oversmoothed.', 'Choose a preset first, then tune patch size, stride, finest scale and refinement iterations.', 'flow', 'patch search → propagation → dense refinement'),
  entry('optical-flow-tvl1', 'Dual TV-L1 optical flow', 'Motion', ['optflow_DualTVL1OpticalFlow', 'optflow_createOptFlow_DualTVL1'], 'Estimate flow with a robust data term and a total-variation smoothness penalty.', 'Preserve motion boundaries while reducing sensitivity to some brightness outliers.', ['Warp the second image using the current flow.', 'Optimize the robust brightness residual and spatial regularization.', 'Repeat warping and coarse-to-fine refinement.'], 'Regularization can remove small or thin motion. More iterations increase cost and do not resolve genuinely invisible regions.', 'lambda balances data and smoothness; scales and warps control large-motion refinement; stopping settings control work.', 'flow', 'energy = robust brightness residual + total variation of flow'),
  entry('background-mog2', 'MOG2 background subtraction', 'Motion', ['BackgroundSubtractorMOG2', 'createBackgroundSubtractorMOG2'], 'Learn a mixture of colour distributions at each pixel and flag observations that do not fit the background.', 'Detect moving regions in a mostly stationary-camera sequence.', ['Compare the current pixel with its learned mixture components.', 'Update component weights and statistics.', 'Classify the observation as background, foreground or a possible shadow.'], 'Camera motion changes the meaning of each pixel. Long-stationary foreground can be absorbed into the background.', 'history and learningRate control adaptation; variance thresholds control classification; shadow detection adds a separate mask label.', 'background', 'pixel history → mixture model → foreground mask'),
  entry('background-knn', 'KNN background subtraction', 'Motion', ['BackgroundSubtractorKNN', 'createBackgroundSubtractorKNN'], 'Classify a pixel using how many nearby samples in its recent history agree with it.', 'Extract moving foreground from a relatively fixed camera without fitting a Gaussian mixture.', ['Maintain a history of pixel observations.', 'Count samples close to the current colour.', 'Accept supported observations as background and update the history.'], 'It shares the fixed-camera and adaptation limitations of other per-pixel background models.', 'history, distance threshold and required neighbour count control adaptation and background acceptance.', 'background', 'background when enough historical samples are nearby'),
  entry('kalman', 'Kalman filtering', 'Motion', ['KalmanFilter'], 'Combine a predicted state with a noisy observation using their estimated uncertainties.', 'Smooth position or velocity measurements and predict where a tracked object will appear next.', ['Predict the next state and covariance through the motion model.', 'Compare the measurement with the predicted observation.', 'Apply a covariance-weighted correction.'], 'The basic filter assumes linear models and specified noise statistics. It estimates state, but does not detect the object or solve data association.', 'Set transitionMatrix, measurementMatrix, processNoiseCov and measurementNoiseCov to match the state and sensor model.', 'kalman', 'corrected state = prediction + gain × measurement residual'),
  entry('tracker-csrt', 'CSRT tracking', 'Motion', ['TrackerCSRT'], 'Track an initialized object with correlation filters weighted by channel and spatial reliability.', 'Follow a selected object when a more detailed CPU tracker is acceptable.', ['Initialize a bounding box and appearance model.', 'Correlate the learned filters with the next search region.', 'Update position, scale and reliable appearance support.'], 'Trackers can drift or lose an occluded object. A successful update should still be checked against application-specific confidence and geometry.', 'Initialize on a clear frame. Search padding, feature channels and scale settings trade work against robustness.', 'tracking', 'initialized box → local search → model update'),
  entry('tracker-kcf', 'KCF tracking', 'Motion', ['TrackerKCF'], 'Use a kernelized correlation filter to locate a learned appearance in a local search region.', 'Follow a single initialized object with relatively low CPU cost.', ['Learn a filter from shifted versions of the target patch.', 'Evaluate the response in the next frame.', 'Move to the response peak and update appearance.'], 'Fast local tracking does not guarantee recovery after occlusion or large deformation. Re-detection is a separate task.', 'Descriptor, kernel and learning settings control the appearance model. Check the update result before trusting the box.', 'tracking', 'appearance correlation → response peak → new box'),
  entry('tracker-mil', 'MIL tracking', 'Motion', ['TrackerMIL'], 'Learn an online appearance classifier from bags of nearby positive and negative samples.', 'Track a user-selected object when initialization is approximate and online adaptation is useful.', ['Sample patches around the current target.', 'Update a multiple-instance learning classifier.', 'Choose the best-scoring patch in the next search area.'], 'Appearance updates can reinforce drift. Occlusion and abrupt displacement remain difficult.', 'Sampling radii and candidate counts affect the search region and update cost.', 'tracking', 'candidate patches → online classifier → selected location'),
  entry('camera-calibration', 'Camera calibration', '3D vision', ['calibrateCamera', 'calibrateCameraExtended', 'findChessboardCorners', 'findCirclesGrid'], 'Estimate a camera’s intrinsic parameters and lens distortion from known target geometry.', 'Measure geometry, remove lens distortion, or prepare images for stereo reconstruction.', ['Detect known target points in multiple views.', 'Relate their 3D target coordinates to observed 2D pixels.', 'Optimize intrinsics, distortion and each view’s pose to reduce reprojection error.'], 'Poor target coverage or nearly identical views leave parameters weakly constrained. A low average error alone does not prove calibration quality.', 'Use consistent physical units and image size. Calibration flags determine which model parameters are fitted or fixed.', 'camera', '3D target → camera pose → projection → observed pixel'),
  entry('undistortion', 'Lens undistortion', '3D vision', ['undistort', 'undistortPoints', 'initUndistortRectifyMap'], 'Invert a calibrated lens model to map distorted observations onto an idealized camera image.', 'Straighten lens curvature and prepare measurements for geometric estimation.', ['Use camera intrinsics and distortion coefficients.', 'Build an inverse sampling map for the desired output camera.', 'Remap the image, or directly correct selected point coordinates.'], 'The output may have uncovered borders or a changed field of view. Point APIs can return normalized coordinates unless a projection matrix is supplied.', 'Choose the new camera matrix to control crop and field of view. Cache maps for repeated frames of the same geometry.', 'camera', 'distorted pixels → calibrated inverse model → ideal coordinates'),
  entry('pnp', 'Perspective-n-point pose', '3D vision', ['solvePnP', 'solvePnPRansac', 'solvePnPGeneric', 'projectPoints', 'Rodrigues'], 'Estimate a camera-relative object pose from known 3D points and their 2D image observations.', 'Place an overlay on a calibrated marker or measure the pose of known geometry.', ['Match 3D object coordinates to image points.', 'Solve a rotation and translation consistent with the camera model.', 'Refine and inspect reprojection errors; use robust sampling when correspondences contain outliers.'], 'Some configurations have multiple pose solutions. Units, point order, camera calibration and coordinate conventions must agree.', 'flags select the solver with its minimum point count and geometry requirements. RANSAC thresholds use image coordinates.', 'camera', 'camera point = R · object point + t'),
  entry('epipolar-geometry', 'Fundamental and essential matrices', '3D vision', ['findFundamentalMat', 'findEssentialMat', 'recoverPose', 'computeCorrespondEpilines'], 'Constrain where a point from one camera view can appear in another.', 'Reject inconsistent matches, recover relative camera motion, or prepare a two-view reconstruction.', ['Match corresponding image points.', 'Estimate the epipolar relation with a robust method.', 'For a calibrated essential matrix, choose a pose consistent with points in front of both cameras.'], 'Pure rotation, weak baseline and degenerate scenes can prevent reliable depth or translation estimates. Translation recovered from an essential matrix has unknown scale.', 'Essential geometry needs calibrated or normalized coordinates. Inspect inliers and cheirality, not only the returned matrix.', 'stereo', 'x₂ᵀ F x₁ = 0'),
  entry('stereo-bm', 'Stereo block matching', '3D vision', ['StereoBM'], 'Find horizontal correspondences between rectified stereo images using local block similarity.', 'Estimate a fast, coarse disparity map from a calibrated stereo pair.', ['Rectify images so corresponding points share scanlines.', 'Compare a local block across candidate horizontal shifts.', 'Select a supported disparity and reject weak or inconsistent matches.'], 'Uniform regions, reflections and occlusion cause invalid disparities. The raw output uses a fixed-point scale and needs proper conversion.', 'numDisparities sets search range; blockSize trades detail against stability; uniqueness and texture settings reject uncertain matches.', 'stereo', 'depth ∝ focal length × baseline / disparity'),
  entry('stereo-sgbm', 'Semi-global stereo matching', '3D vision', ['StereoSGBM'], 'Aggregate stereo matching costs along multiple directions while penalizing disparity jumps.', 'Obtain more coherent depth maps than independent local block matching.', ['Compute local costs for each candidate disparity.', 'Accumulate costs along paths with small- and large-jump penalties.', 'Choose disparities and perform consistency or speckle filtering.'], 'Smoothness can flatten thin structures and cross depth boundaries. It cannot create trustworthy depth where correspondence is absent.', 'P1 and P2 set smoothness penalties; mode changes path aggregation and cost; tune disparity range to camera geometry.', 'stereo', 'matching cost + penalties for disparity changes'),
  entry('triangulation', 'Triangulation', '3D vision', ['triangulatePoints', 'sfm_triangulatePoints'], 'Recover a 3D point by intersecting the viewing rays implied by multiple camera observations.', 'Reconstruct sparse geometry from matched points and known camera matrices.', ['Back-project each observation through its camera model.', 'Solve for the point best satisfying the projection equations.', 'Convert homogeneous coordinates and check depth and reprojection error.'], 'Nearly parallel rays create unstable depth. All observations and camera matrices must use compatible coordinate systems.', 'Use well-conditioned views and reject points behind cameras or with poor reprojection consistency.', 'stereo', 'corresponding rays → least-squares 3D intersection'),
  entry('aruco', 'ArUco markers', 'Detection', ['aruco_ArucoDetector', 'aruco_generateImageMarker', 'aruco_getPredefinedDictionary', 'aruco_CharucoDetector'], 'Detect square coded markers and recover their identities and ordered corners.', 'Build fiducial tracking, calibration boards and known-geometry pose inputs.', ['Locate square-like candidates and refine their corners.', 'Rectify each candidate into its code grid.', 'Decode against a dictionary and reject invalid codes.'], 'Detection returns image geometry, not a fully calibrated world pose. Motion blur, glare and too-small markers reduce reliability.', 'Use the same dictionary when generating and detecting. Supply the marker’s physical size and camera calibration for pose estimation.', 'marker', 'square candidate → rectified bit grid → dictionary ID'),
  entry('qr-code', 'QR code detection', 'Detection', ['QRCodeDetector', 'QRCodeDetectorAruco', 'wechat_qrcode_WeChatQRCode'], 'Locate QR structures, rectify the code and decode its payload.', 'Read QR labels in images or browser camera frames.', ['Locate candidate finder-pattern arrangements.', 'Estimate code geometry and sample its module grid.', 'Decode codewords and apply error correction.'], 'Some detector variants require application-supplied models. A detected quadrilateral can still fail to decode.', 'Choose single or multi-code methods. Preserve adequate module resolution and inspect both returned geometry and decoded data.', 'marker', 'finder patterns → module grid → decoded bytes'),
  entry('histogram-equalization', 'Histogram equalization', 'Colour', ['equalizeHist', 'calcHist', 'calcBackProject'], 'Redistribute grayscale intensities using their cumulative histogram.', 'Increase global contrast when useful intensities occupy a narrow range.', ['Count the occurrence of each intensity.', 'Form a normalized cumulative distribution.', 'Map each input intensity to its cumulative rank.'], 'Equalization can amplify noise and shift brightness. Applying it independently to colour channels changes colour relationships.', 'equalizeHist accepts 8-bit grayscale. calcHist offers general histogram building; backprojection maps histogram likelihoods back to pixels.', 'histogram', 'output = normalized cumulative histogram(input)'),
  entry('clahe', 'CLAHE local contrast', 'Colour', ['CLAHE', 'createCLAHE'], 'Equalize local histograms while limiting how much a concentrated bin can amplify contrast.', 'Reveal detail under uneven illumination without the strongest noise amplification of unrestricted local equalization.', ['Split the image into tiles and build their histograms.', 'Clip large bins and redistribute their excess counts.', 'Interpolate mappings between tiles to avoid abrupt boundaries.'], 'It can still amplify noise and create unnatural contrast. Work on a suitable luminance channel when preserving colour matters.', 'clipLimit controls clipping; tileGridSize sets the number of tiles, not their pixel dimensions.', 'histogram', 'local histogram → clipped distribution → interpolated mapping'),
  entry('colour-conversion', 'Colour-space conversion', 'Colour', ['cvtColor', 'cvtColorTwoPlane'], 'Re-express pixels in a different channel order or colour representation.', 'Convert camera frames to grayscale, select colours in HSV, or adapt data for codecs and models.', ['Interpret the input channels and their expected numeric range.', 'Apply the selected colour transform.', 'Write the output channel order and representation.'], 'BGR, RGB and RGBA are different conventions. Floating-point conversions may expect normalized ranges; a type change alone does not rescale values.', 'The COLOR_* code defines the conversion. Canvas helpers use RGBA; native decoded images use BGR or BGRA.', 'colour', 'channel meaning + numeric range + transform → new representation'),
  entry('in-range', 'Colour range masks', 'Colour', ['inRange'], 'Keep pixels whose channel values all lie within specified lower and upper bounds.', 'Select controlled colours or gate pixels by intensity and feature ranges.', ['Compare every channel with its allowed interval.', 'Combine the channel comparisons.', 'Write an 8-bit binary mask.'], 'Lighting changes move colours across fixed bounds. Cyclic hue ranges may need two masks joined together.', 'Bounds are inclusive. Choose the colour representation before setting the limits.', 'threshold', 'mask = AND over channels of lower ≤ value ≤ upper'),
  entry('dft', 'Discrete Fourier transform', 'Signal', ['dft', 'idft', 'mulSpectrums', 'getOptimalDFTSize'], 'Represent a signal as a combination of spatial frequencies.', 'Filter periodic noise, analyze textures, or perform frequency-domain correlation.', ['Transform spatial samples into frequency coefficients.', 'Modify magnitudes or combine spectra while preserving required complex structure.', 'Apply an inverse transform to return to spatial data.'], 'Boundary discontinuities spread energy across frequencies. Padding, windowing, complex layouts and inverse scaling need deliberate choices.', 'DFT flags control direction, scaling and complex layout. Use supported optimal sizes when padding is appropriate.', 'frequency', 'spatial samples ↔ complex frequency coefficients'),
  entry('dct', 'Discrete cosine transform', 'Signal', ['dct', 'idct'], 'Express a signal using cosine basis functions with an implicit even boundary extension.', 'Compact smooth image content into a small set of coefficients or study block compression.', ['Project samples onto cosine basis functions.', 'Retain or modify selected frequency coefficients.', 'Reconstruct with the inverse cosine transform.'], 'Removing high frequencies loses detail; independent block processing can introduce visible block boundaries.', 'DFT_INVERSE selects reconstruction in dct; check supported dimensions and floating-point depth.', 'frequency', 'samples ↔ weighted cosine basis functions'),
  entry('nonlocal-means', 'Non-local means denoising', 'Photography', ['fastNlMeansDenoising', 'fastNlMeansDenoisingColored', 'fastNlMeansDenoisingMulti'], 'Average pixels whose surrounding patches look similar, even when they are not immediate neighbours.', 'Reduce image noise while preserving recurring texture and structures.', ['Compare the patch around a pixel with nearby candidate patches.', 'Convert patch similarity into weights.', 'Average corresponding pixel values using those weights.'], 'Strong filtering can make textures waxy. Larger search windows cost more, and multi-frame variants depend on temporal consistency.', 'h controls filtering strength; templateWindowSize sets patch size; searchWindowSize sets the candidate region.', 'denoise', 'weight depends on patch similarity, not only pixel distance'),
  entry('inpainting', 'Image inpainting', 'Photography', ['inpaint'], 'Fill a masked region by propagating nearby image structure and colour into it.', 'Remove small scratches or fill narrow missing regions when a plausible continuation is sufficient.', ['Mark the pixels to replace.', 'Advance inward from the known boundary.', 'Estimate missing values using the chosen Telea or Navier-Stokes method.'], 'The result is synthesized. It is not evidence of the original hidden content, especially across large missing objects.', 'inpaintRadius controls the local neighbourhood; flags select the algorithm. Keep the mask distinct from observed-data coverage.', 'inpaint', 'known boundary → inward propagation → synthesized fill'),
  entry('seamless-cloning', 'Seamless cloning', 'Photography', ['seamlessClone', 'illuminationChange', 'textureFlattening'], 'Blend a region by solving for pixel values that fit selected image gradients and boundary conditions.', 'Insert a patch with smoother boundary appearance or edit illumination inside a selected region.', ['Choose the source gradients and a destination boundary.', 'Solve a Poisson-style reconstruction inside the mask.', 'Combine the solved region with the destination image.'], 'The solution can shift colours to match the destination boundary. It does not guarantee physically consistent lighting or semantics.', 'The mask and centre define placement; NORMAL_CLONE and MIXED_CLONE choose different gradient sources.', 'inpaint', 'match interior gradients while respecting boundary values'),
  entry('hdr', 'HDR merging and tone mapping', 'Photography', ['createMergeDebevec', 'createMergeRobertson', 'createMergeMertens', 'createTonemap', 'createTonemapDrago', 'createTonemapReinhard', 'createTonemapMantiuk'], 'Combine exposure information or fuse well-exposed regions, then map the result into a displayable range.', 'Recover a wider scene brightness range from an exposure bracket or create an exposure-fused image.', ['Align the bracketed images and account for exposure when required.', 'Merge radiance estimates or fuse contrast, saturation and exposure quality.', 'Tone-map a radiance result for the target display.'], 'Moving subjects cause ghosts. Exposure fusion is not the same as calibrated HDR radiance reconstruction.', 'Debevec/Robertson use exposure information; Mertens performs exposure fusion. Tone-mapper parameters change appearance, not captured evidence.', 'pyramid', 'exposures → radiance or fusion → display mapping'),
  entry('guided-filter', 'Guided filtering', 'Filtering', ['ximgproc_guidedFilter', 'ximgproc_createGuidedFilter'], 'Use a guidance image to decide how a local linear model should smooth another image.', 'Refine masks, smooth depth or transfer edge structure from a cleaner guide.', ['Fit a local linear relationship between guide and filtered signal.', 'Regularize the model to avoid unstable fits.', 'Average overlapping local predictions.'], 'Guide texture can be transferred into the output. The guide and input must be geometrically aligned.', 'radius sets local support; eps controls edge sensitivity relative to the guide’s value scale.', 'convolution', 'output ≈ a · guide + b within each local window'),
  entry('thinning', 'Skeleton thinning', 'Morphology', ['ximgproc_thinning'], 'Iteratively remove boundary pixels while trying to preserve the connectivity of a binary shape.', 'Reduce strokes or elongated regions to a compact centreline representation.', ['Identify removable boundary pixels.', 'Apply topology-preserving deletion rules in sub-iterations.', 'Repeat until no more pixels can be removed.'], 'Small boundary defects can create skeleton branches. A skeleton is not necessarily the same as a medial axis from Euclidean distances.', 'Use a binary 8-bit image and choose the supported Zhang-Suen or Guo-Hall method.', 'morphology', 'thick connected region → topology-preserving thin strokes'),
  entry('superpixels', 'SLIC, SEEDS and LSC superpixels', 'Segmentation', ['ximgproc_SuperpixelSLIC', 'ximgproc_createSuperpixelSLIC', 'ximgproc_SuperpixelSEEDS', 'ximgproc_createSuperpixelSEEDS', 'ximgproc_SuperpixelLSC', 'ximgproc_createSuperpixelLSC'], 'Group nearby pixels into small coherent regions to reduce the cost of later reasoning.', 'Build region-level features, simplify segmentation inputs, or visualize local image structure.', ['Initialize a spatial partition or local cluster centres.', 'Refine assignments using the selected colour/spatial objective.', 'Enforce connectivity and expose region labels or boundaries.'], 'Superpixels are an oversegmentation, not semantic objects. The algorithms optimize different objectives and have distinct tuning parameters.', 'SLIC balances colour and spatial distance; SEEDS updates block partitions; LSC uses a transformed feature-space clustering objective.', 'components', 'pixels → locally coherent regions → region-level processing'),
  entry('kmeans', 'K-means clustering', 'Machine learning', ['kmeans'], 'Partition feature vectors around a fixed number of learned centres.', 'Quantize colours, group visual features or build a visual vocabulary.', ['Initialize K centres.', 'Assign every sample to its nearest centre.', 'Replace centres with cluster means and repeat.'], 'Results depend on initialization and feature scaling. Spherical Euclidean clusters may not match the underlying structure.', 'K selects the number of clusters; attempts repeats initialization; KMEANS_PP_CENTERS improves centre seeding.', 'clusters', 'minimize Σ ||sample − assigned centre||²'),
  entry('svm', 'Support vector machines', 'Machine learning', ['ml_SVM', 'ml_SVM_create'], 'Learn a decision boundary that balances class separation against margin violations.', 'Classify image descriptors or build small supervised vision models.', ['Arrange labelled feature vectors consistently.', 'Select a linear or kernel-based decision model.', 'Optimize the margin objective and predict labels or scores for new samples.'], 'Training accuracy does not estimate generalization. Scaling, validation splits and hyperparameter selection matter.', 'C controls violation cost; kernel parameters set similarity; choose the correct SVM type for classification, regression or one-class learning.', 'classifier', 'decision boundary with a margin around supported samples'),
  entry('knn-classifier', 'K-nearest-neighbour classification', 'Machine learning', ['ml_KNearest', 'ml_KNearest_create'], 'Predict a sample from the labels or values of nearby training examples.', 'Build a simple classifier for small descriptor sets or establish a baseline before fitting a more complex model.', ['Store training feature vectors and responses.', 'Find the closest K vectors to a query.', 'Aggregate their labels or numeric responses.'], 'Prediction depends strongly on feature scaling and distance. Query cost and memory grow with the stored training data.', 'K trades local sensitivity against smoothing; isClassifier selects classification or regression behavior.', 'clusters', 'query → K nearest examples → vote or average'),
  entry('random-forests', 'Random forests', 'Machine learning', ['ml_RTrees', 'ml_RTrees_create', 'ml_DTrees', 'ml_Boost'], 'Combine decisions from trees that split feature space into regions.', 'Classify or regress from engineered visual features without requiring a linear boundary.', ['Train trees using feature tests at internal nodes.', 'Follow the query’s feature values through each tree.', 'Aggregate leaf predictions across the ensemble.'], 'Random forests, individual trees and boosting use different training strategies. None removes the need for representative held-out validation.', 'Depth, minimum sample count and ensemble size control capacity and cost. Variable types and missing-data conventions must match training.', 'classifier', 'feature tests → tree leaves → ensemble prediction'),
  entry('pca', 'Principal component analysis', 'Machine learning', ['PCACompute', 'PCACompute2', 'PCAProject', 'PCABackProject'], 'Find orthogonal directions that explain the greatest variance in centred data.', 'Reduce descriptor dimensionality, compress correlated features or visualize a dataset.', ['Subtract the training mean.', 'Find covariance eigenvectors ordered by explained variance.', 'Project samples onto the retained directions.'], 'Large variance is not always task-relevant information. Use the training mean and basis consistently on later data.', 'maxComponents or retainedVariance selects dimensionality. Scale heterogeneous features before fitting when units differ.', 'clusters', 'projection = (sample − mean) · retained basis'),
  entry('dnn-inference', 'Neural-network inference', 'Deep learning', ['dnn_Net', 'dnn_readNetFromONNX', 'dnn_blobFromImage', 'dnn_blobFromImages'], 'Execute a trained model by passing tensors through its computation graph.', 'Run classifiers, detectors, segmenters or other supported models in a browser or Node worker.', ['Load the model bytes into the instance’s virtual filesystem.', 'Prepare input tensors with the model’s exact layout, size and normalization.', 'Run forward inference and interpret the named outputs.'], 'Compilation of DNN does not imply every operator or model is supported. This build runs on CPU WASM and does not enable WebGPU.', 'Match model input names, RGB/BGR order, scale, mean and layout. Postprocessing is model-specific.', 'network', 'preprocess → learned layers → model-specific outputs'),
  entry('nms', 'Non-maximum suppression', 'Detection', ['dnn_NMSBoxes', 'dnn_NMSBoxesBatched', 'dnn_softNMSBoxes'], 'Reduce overlapping detector proposals by retaining the most useful scored boxes.', 'Turn dense object-detector output into a smaller set of final detections.', ['Sort or select candidate boxes by confidence.', 'Keep a strong box and compare overlaps with remaining candidates.', 'Remove or decay competing scores according to the chosen suppression rule.'], 'Nearby objects can suppress each other. Class handling and box coordinate conventions must match the model output.', 'score_threshold removes weak proposals; nms_threshold controls overlap tolerance; batched NMS separates classes.', 'boxes', 'IoU = intersection area / union area'),
  entry('dnn-super-resolution', 'Learned super-resolution', 'Deep learning', ['dnn_superres_DnnSuperResImpl', 'dnn_superres_DnnSuperResImpl_create'], 'Use a trained network to infer a higher-resolution image from a lower-resolution input.', 'Produce model-based upscaled images when a supported model and its expected scale are available.', ['Load a compatible super-resolution model.', 'Set its architecture name and scale factor.', 'Run the network and assemble the high-resolution output.'], 'Generated fine detail is inferred, not a recovered observation. Models can hallucinate texture and use substantial memory.', 'setModel must agree with the loaded network and scale. Benchmark small images first on the CPU WASM backend.', 'network', 'low-resolution input → learned reconstruction → larger image'),
  entry('ocr', 'Tesseract OCR', 'Text', ['text_OCRTesseract'], 'Recognize text from image regions using supplied language data and a chosen page segmentation mode.', 'Read labels, scanned documents or prepared text crops locally.', ['Provide the appropriate trained language data.', 'Segment the image into the text structure expected by the selected mode.', 'Recognize characters and return text with available component information.'], 'Language data is an application asset, not bundled. Small text, perspective distortion and complex backgrounds need preprocessing.', 'The language, engine mode and page segmentation mode should match the input. Keep text resolution adequate without inventing extra detail.', 'text', 'text image → line/word structure → recognized symbols'),
  entry('text-detection', 'Text-region detection', 'Text', ['text_computeNMChannels', 'text_createERFilterNM1', 'text_createERFilterNM2', 'text_detectRegions', 'text_TextDetectorCNN'], 'Find candidate text regions before character recognition.', 'Locate scene text so recognition can work on focused, rectified crops.', ['Construct channels or features suited to the chosen detector.', 'Score region candidates with the detector’s model.', 'Group compatible candidates into text regions.'], 'Detection locates likely text; it does not decode the words. Classical ER filters and CNN detectors require different models and preprocessing.', 'Load the detector’s required classifier assets and use its documented channel, scale and grouping settings.', 'text', 'candidate regions → text likelihood → grouped text boxes'),
  entry('image-hashing', 'Perceptual image hashes', 'Similarity', ['img_hash_PHash', 'img_hash_AverageHash', 'img_hash_BlockMeanHash', 'img_hash_ColorMomentHash', 'img_hash_MarrHildrethHash', 'img_hash_RadialVarianceHash'], 'Compress selected visual statistics into a small representation for image comparison.', 'Find near-duplicate candidates or group visually related images before a more precise check.', ['Normalize or transform the image according to the hash algorithm.', 'Summarize low-frequency, block, colour, edge or radial structure.', 'Compare descriptors with the algorithm’s prescribed distance.'], 'A perceptual hash is not a cryptographic identity and can collide. Algorithms respond differently to crops, rotation, colour shifts and overlays.', 'Choose a hash for the expected changes, then calibrate a distance threshold on representative positive and negative examples.', 'frequency', 'image → compact visual descriptor → distance'),
  entry('quality-metrics', 'PSNR and SSIM quality metrics', 'Similarity', ['PSNR', 'quality_QualityPSNR', 'quality_QualitySSIM', 'quality_QualityMSE', 'quality_QualityGMSD', 'quality_QualityBRISQUE'], 'Measure selected differences or quality cues between images, or estimate quality without a reference.', 'Compare reconstruction outputs when the metric’s assumptions match the task.', ['Align the compared images and agree on range and channel meaning.', 'Compute error statistics, local structure, gradient similarity or learned natural-scene features.', 'Aggregate the metric while preserving any useful spatial quality map.'], 'A high score does not prove perceptual correctness or semantic fidelity. BRISQUE is a learned no-reference method and needs its model assets.', 'PSNR requires the correct peak range; SSIM depends on local statistics. Report unknown pixels separately instead of treating them as correct.', 'quality', 'PSNR = 10 log10(peak² / MSE)'),
  entry('saliency', 'Visual saliency', 'Detection', ['saliency_StaticSaliencySpectralResidual', 'saliency_StaticSaliencyFineGrained', 'saliency_MotionSaliencyBinWangApr2014', 'saliency_ObjectnessBING'], 'Estimate conspicuous regions or candidate object windows from appearance or motion.', 'Prioritize candidate regions for later processing or explore image attention cues.', ['Extract the method’s spectral, local-contrast, motion or gradient features.', 'Score locations that differ from their surrounding regularities.', 'Return a saliency map or candidate windows for downstream use.'], 'Saliency is not an object label, and attractive texture can score more highly than the intended subject. BING needs trained model data.', 'Select a static, motion or objectness method to match the task. Interpret each output on its own documented scale.', 'segmentation', 'visual regularity → local exception → candidate attention'),
  entry('alpha-matting', 'Alpha matting', 'Segmentation', ['alphamat_infoFlow'], 'Estimate fractional foreground coverage using an image and a trimap of known foreground, background and unknown pixels.', 'Recover soft boundaries around hair, motion blur or translucent edges with suitable user or model guidance.', ['Provide confident foreground and background regions.', 'Propagate colour and affinity information through the unknown region.', 'Solve for intermediate alpha coverage.'], 'The trimap is evidence supplied by the application. Similar colours and broad unknown regions can make the matte ambiguous.', 'Prepare the trimap with the exact labels and type the API expects. Keep alpha separate from a binary semantic mask.', 'matting', 'observed colour = α·foreground + (1−α)·background'),
  entry('white-balance', 'White balance', 'Colour', ['xphoto_SimpleWB', 'xphoto_GrayworldWB', 'xphoto_LearningBasedWB', 'xphoto_createSimpleWB', 'xphoto_createGrayworldWB', 'xphoto_createLearningBasedWB'], 'Estimate channel gains or mappings that reduce an image’s illumination colour cast.', 'Normalize colour under changing lighting before display or carefully calibrated analysis.', ['Measure channel statistics or learned illumination features.', 'Estimate the correction under the selected assumptions.', 'Apply channel corrections and preserve the intended output range.'], 'Gray-world assumes average reflectance is neutral; percentile stretching and learned models have different assumptions. Strongly coloured scenes can violate them.', 'Choose a method based on the scene distribution and available model. Avoid silently changing colour in tasks that require original pixel evidence.', 'colour', 'estimated illuminant → channel correction → adjusted colour'),
  entry('stitching', 'Panorama stitching', 'Photography', ['Stitcher', 'PyRotationWarper', 'detail_MultiBandBlender', 'detail_FeatherBlender'], 'Combine overlapping images through matching, camera estimation, warping and blending.', 'Create panoramas when the scene and camera motion fit the selected stitching model.', ['Match overlapping features and estimate camera relationships.', 'Warp images onto a common projection and select seams.', 'Compensate exposure and blend overlaps across scales.'], 'Parallax, moving objects and weak overlap produce ghosts or alignment failures. A stitcher is not a general scene reconstruction system.', 'Choose panorama or scan assumptions deliberately. Check the returned status and inspect overlap consistency before trusting the composite.', 'pyramid', 'matches → common projection → seams and blending'),
  entry('icp', 'Iterative closest point', '3D vision', ['ppf_match_3d_ICP'], 'Refine the relative pose of two 3D surfaces by alternating correspondences and alignment.', 'Align point clouds that already have a reasonable initial pose.', ['Associate source points with nearby target surface points.', 'Solve a pose update that reduces the correspondence residual.', 'Transform and repeat until improvement or iteration limits stop the process.'], 'ICP is a local optimizer. Symmetry, partial overlap, outliers and a poor initialization can lead to the wrong alignment.', 'Sampling, rejection scale, iteration count and tolerance trade detail against cost and robustness.', 'ecc', 'correspond → fit pose → transform → repeat'),
  entry('structured-light', 'Structured-light decoding', '3D vision', ['structured_light_GrayCodePattern', 'structured_light_SinusoidalPattern'], 'Recover projector-camera correspondences from a sequence of known projected patterns.', 'Measure scene shape with a calibrated projector and camera under controlled capture.', ['Project and capture the required pattern sequence.', 'Decode intensity changes into projector coordinates or phase.', 'Use calibration to turn correspondences into 3D geometry.'], 'Motion between captures, shadows and reflections invalidate codes. Pattern generation alone is not a complete reconstruction.', 'Gray-code and sinusoidal methods have different sequences and calibration requirements. Thresholds govern accepted illumination evidence.', 'marker', 'projected codes → decoded correspondences → triangulation'),
  entry('phase-unwrapping', 'Phase unwrapping', 'Signal', ['phase_unwrapping_HistogramPhaseUnwrapping'], 'Recover a continuous phase field from measurements wrapped into a fixed angular interval.', 'Process structured-light phase or other periodic measurements when a suitable quality map is available.', ['Estimate local phase reliability.', 'Resolve neighbouring differences modulo a full cycle.', 'Propagate consistent cycle offsets through reliable regions.'], 'Discontinuities, holes and noise can make the absolute cycle assignment ambiguous. Unwrapping does not supply an external absolute phase reference.', 'Set the image dimensions and reliability histogram parameters to match the input phase map.', 'polar', 'unwrapped phase = wrapped phase + 2π·integer offset'),
  entry('retina', 'Retina-inspired processing', 'Filtering', ['bioinspired_Retina'], 'Apply a bio-inspired model with separate detail/colour and motion-sensitive processing pathways.', 'Explore local adaptation, dynamic-range compression and transient visual responses.', ['Apply local adaptation and spatial filtering to the input.', 'Update the model’s temporal state.', 'Read the parvocellular and magnocellular pathway outputs.'], 'Temporal state means consecutive calls are related. The outputs are transformed visual signals, not a calibrated substitute for original intensities.', 'Configure sampling, colour mode and pathway adaptation parameters for the sequence. Reset state deliberately between unrelated clips.', 'background', 'input → spatial/temporal adaptation → detail and transient pathways'),
]

/** Atlas categories in first-appearance order, shared by navigation and discovery filters. */
export const algorithmGroups = [...new Set(algorithms.map(algorithm => algorithm.category))].map(category => ({
  category,
  algorithms: algorithms.filter(algorithm => algorithm.category === category),
}))
